import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.extern .shared .b8 smem[];
.visible .entry conv_transpose2d_nchw_kernel(
    .param .u64 a_in,
    .param .u64 a_w,
    .param .u64 a_out,
    .param .u64 a_bias,
    .param .s32 has_bias,
    .param .s32 total,
    .param .s32 batch,
    .param .s32 in_ch,
    .param .s32 in_h,
    .param .s32 in_w,
    .param .s32 out_ch,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 k_h,
    .param .s32 k_w,
    .param .s32 s_h,
    .param .s32 s_w,
    .param .s32 p_h,
    .param .s32 p_w,
    .param .s32 d_h,
    .param .s32 d_w,
    .param .s32 groups,
    .param .s32 in_per_group,
    .param .s32 out_per_group
)
{
    .reg .pred %p<32>;
    .reg .u32 %u<4>;
    .reg .s32 %r<112>;
    .reg .s32 %rs<8>;
    .reg .f32 %f<40>;
    .reg .u64 %rd<32>;
    ld.param.u64 %rd1, [a_in];
    ld.param.u64 %rd2, [a_w];
    ld.param.u64 %rd3, [a_out];
    ld.param.u64 %rd4, [a_bias];
    ld.param.s32 %r1, [has_bias];
    ld.param.s32 %r2, [total];
    ld.param.s32 %r3, [batch];
    ld.param.s32 %r4, [in_ch];
    ld.param.s32 %r5, [in_h];
    ld.param.s32 %r6, [in_w];
    ld.param.s32 %r7, [out_ch];
    ld.param.s32 %r8, [out_h];
    ld.param.s32 %r9, [out_w];
    ld.param.s32 %r10, [k_h];
    ld.param.s32 %r11, [k_w];
    ld.param.s32 %r12, [s_h];
    ld.param.s32 %r13, [s_w];
    ld.param.s32 %r14, [p_h];
    ld.param.s32 %r15, [p_w];
    ld.param.s32 %r16, [d_h];
    ld.param.s32 %r17, [d_w];
    ld.param.s32 %r18, [groups];
    ld.param.s32 %r19, [in_per_group];
    ld.param.s32 %r20, [out_per_group];
    // transposed-weight layout constants (used by staging and compute)
    mul.lo.s32 %r58, %r20, %r10;
    mul.lo.s32 %r58, %r58, %r11;        // out_per_group*kh*kw
    add.s32 %r96, %r19, 3;
    div.s32 %r96, %r96, 4;
    mul.lo.s32 %r96, %r96, 4;           // W_TAP_STRIDE = ceil(in_per_group/4)*4
    mul.lo.s32 %r97, %r58, %r96;        // padded weight floats per group
    sub.s32 %r95, %r19, 3;              // ic vector-loop limit
    mov.u32 %u1, %tid.x;
    mov.u32 %u2, %ntid.x;
    mov.u32 %u3, %ctaid.x;
    cvt.s32.u32 %r21, %u1;
    cvt.s32.u32 %r22, %u2;
    cvt.s32.u32 %r23, %u3;
    // CTA-level tiling: one CTA covers (batch b, group g, output row oh)
    // and OW_TILE consecutive output columns for all out_per_group channels.
    // OW_TILE = 4 * ntid / out_per_group
    div.s32 %r45, %r22, %r20;      // HALF = ntid / out_per_group
    mul.lo.s32 %r24, %r45, 4;      // OW_TILE = 4*HALF (4-way register blocking over ow)
    // num_ow_tiles = ceil(out_w / OW_TILE)
    add.s32 %r25, %r9, %r24;
    sub.s32 %r25, %r25, 1;
    div.s32 %r25, %r25, %r24;
    // decompose ctaid -> (b, g, oh, ow_tile)
    rem.s32 %r26, %r23, %r25;
    div.s32 %r27, %r23, %r25;
    rem.s32 %r28, %r27, %r8;
    div.s32 %r29, %r27, %r8;
    rem.s32 %r30, %r29, %r18;
    div.s32 %r31, %r29, %r18;
    mul.lo.s32 %r32, %r26, %r24;        // ow0
    rem.s32 %r33, %r21, %r45;           // ow_local
    div.s32 %r34, %r21, %r45;           // oc_g
    add.s32 %r35, %r32, %r33;           // ow
    add.s32 %r74, %r35, %r45;           // ow_b = ow + HALF (register-blocked 2nd output)
    add.s32 %r85, %r74, %r45;           // ow_c = ow + 2*HALF (register-blocked 3rd output)
    add.s32 %r86, %r85, %r45;           // ow_d = ow + 3*HALF (register-blocked 4th output)
    mul.lo.s32 %r36, %r30, %r20;
    add.s32 %r36, %r36, %r34;           // oc (global out channel)
    // shared tile dimensions
    // IH_MAX = ((kh-1)*dh)/sh + 2
    sub.s32 %r37, %r10, 1;
    mul.lo.s32 %r37, %r37, %r16;
    div.s32 %r37, %r37, %r12;
    add.s32 %r37, %r37, 2;
    // IW_MAX = ((OW_TILE-1)+(kw-1)*dw)/sw + 2
    sub.s32 %r38, %r11, 1;
    mul.lo.s32 %r38, %r38, %r17;
    add.s32 %r38, %r38, %r24;
    sub.s32 %r38, %r38, 1;
    div.s32 %r38, %r38, %r13;
    add.s32 %r38, %r38, 2;
    mul.lo.s32 %r44, %r37, %r38;        // input plane floats
    // IH_LO = max(0, (oh+ph-(kh-1)*dh)/sh)
    sub.s32 %r46, %r10, 1;
    mul.lo.s32 %r46, %r46, %r16;
    add.s32 %r39, %r28, %r14;
    sub.s32 %r39, %r39, %r46;
    div.s32 %r39, %r39, %r12;
    max.s32 %r39, %r39, 0;
    // IH_HI = min(h-1, (oh+ph)/sh)
    add.s32 %r40, %r28, %r14;
    div.s32 %r40, %r40, %r12;
    sub.s32 %r46, %r5, 1;
    min.s32 %r40, %r40, %r46;
    // IW_LO = max(0, (ow0+pw-(kw-1)*dw)/sw)
    sub.s32 %r46, %r11, 1;
    mul.lo.s32 %r46, %r46, %r17;
    add.s32 %r41, %r32, %r15;
    sub.s32 %r41, %r41, %r46;
    div.s32 %r41, %r41, %r13;
    max.s32 %r41, %r41, 0;
    // IW_HI = min(w-1, (ow0+OW_TILE-1+pw)/sw)
    add.s32 %r42, %r32, %r24;
    sub.s32 %r42, %r42, 1;
    add.s32 %r42, %r42, %r15;
    div.s32 %r42, %r42, %r13;
    sub.s32 %r46, %r6, 1;
    min.s32 %r42, %r42, %r46;
    // W_count = in_per_group*out_per_group*kh*kw
    mul.lo.s32 %r43, %r19, %r20;
    mul.lo.s32 %r43, %r43, %r10;
    mul.lo.s32 %r43, %r43, %r11;
    // shared memory layout: [0..15] zero zone (sink for invalid taps),
    // then transposed weights [oc_g][kh][kw][ic] with per-tap stride padded
    // to a multiple of 4 floats (16B-aligned vector loads), then input tile
    mov.u64 %rd9, smem;
    add.u64 %rd5, %rd9, 16;
    cvt.u64.s32 %rd13, %r97;
    mul.lo.u64 %rd13, %rd13, 4;
    add.u64 %rd6, %rd5, %rd13;
    cvt.u64.s32 %rd14, %r44;
    mul.lo.u64 %rd14, %rd14, 4;         // input plane stride in bytes
    // initialize the zero zone
    setp.lt.s32 %p27, %r21, 4;
    @!%p27 bra L_zinit_done;
    cvt.u64.s32 %rd7, %r21;
    mul.lo.u64 %rd7, %rd7, 4;
    add.u64 %rd7, %rd9, %rd7;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rd7], %f1;
L_zinit_done:
    // cooperative load of this group's weights into shared memory with a
    // transposed layout: smem[tap_lin*W_TAP_STRIDE + ic] (ic contiguous)
    mul.lo.s32 %r46, %r30, %r43;        // g*W_count
    mov.s32 %rs1, %r21;
L_wload:
    setp.lt.s32 %p1, %rs1, %r43;
    @!%p1 bra L_wload_done;
    add.s32 %r47, %r46, %rs1;
    cvt.u64.s32 %rd7, %r47;
    mul.lo.u64 %rd7, %rd7, 4;
    add.u64 %rd7, %rd2, %rd7;
    div.s32 %r49, %rs1, %r58;           // ic
    rem.s32 %r50, %rs1, %r58;           // tap-linear index
    mul.lo.s32 %r51, %r50, %r96;
    add.s32 %r51, %r51, %r49;           // transposed smem float offset
    cvt.u64.s32 %rd8, %r51;
    mul.lo.u64 %rd8, %rd8, 4;
    add.u64 %rd8, %rd5, %rd8;
    cp.async.ca.shared.global [%rd8], [%rd7], 4;
    add.s32 %rs1, %rs1, %r22;
    bra L_wload;
L_wload_done:
    // cooperative load of the reusable input tile into shared memory
    mul.lo.s32 %r48, %r19, %r44;        // total input tile floats
    mov.s32 %rs1, %r21;
L_iload:
    setp.lt.s32 %p2, %rs1, %r48;
    @!%p2 bra L_iload_done;
    div.s32 %r49, %rs1, %r44;           // ic
    rem.s32 %r50, %rs1, %r44;
    div.s32 %r51, %r50, %r38;           // ih_i
    rem.s32 %r52, %r50, %r38;           // iw_i
    add.s32 %r53, %r39, %r51;           // ih
    add.s32 %r54, %r41, %r52;           // iw
    setp.gt.s32 %p3, %r53, %r40;
    setp.gt.s32 %p4, %r54, %r42;
    or.pred %p5, %p3, %p4;
    cvt.u64.s32 %rd8, %rs1;
    mul.lo.u64 %rd8, %rd8, 4;
    add.u64 %rd8, %rd6, %rd8;
    @%p5 bra L_iload_zero;
    mul.lo.s32 %r55, %r30, %r19;
    add.s32 %r55, %r55, %r49;           // g*in_per_group + ic
    mul.lo.s32 %r56, %r31, %r4;
    add.s32 %r56, %r56, %r55;
    mul.lo.s32 %r56, %r56, %r5;
    add.s32 %r56, %r56, %r53;
    mul.lo.s32 %r56, %r56, %r6;
    add.s32 %r56, %r56, %r54;
    cvt.u64.s32 %rd7, %r56;
    mul.lo.u64 %rd7, %rd7, 4;
    add.u64 %rd7, %rd1, %rd7;
    cp.async.ca.shared.global [%rd8], [%rd7], 4;
    bra L_iload_next;
L_iload_zero:
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rd8], %f1;
L_iload_next:
    add.s32 %rs1, %rs1, %r22;
    bra L_iload;
L_iload_done:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    // threads mapped to out-of-range columns finish after staging
    setp.ge.s32 %p6, %r35, %r9;
    @%p6 bra L_ret;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f5, 0f00000000;
    mov.f32 %f9, 0f00000000;
    mov.f32 %f10, 0f00000000;
    setp.lt.s32 %p17, %r74, %r9;
    setp.lt.s32 %p22, %r85, %r9;
    setp.lt.s32 %p23, %r86, %r9;
    // Restructured accumulation: loop nest is kh -> kw -> ic (ic innermost).
    // Tap validity / divisibility and shared-memory offsets are independent
    // of ic, so they are computed once per tap instead of once per (ic,tap),
    // eliminating the emulated div/rem sequences from the channel loop.
    // Fast CTA-uniform row test: does any kh tap hit this output row?
    mov.s32 %r75, 0;
    mov.s32 %rs2, 0;
    add.s32 %r62, %r28, %r14;           // t_h = oh + ph - kh_i*dh
L_rowchk:
    setp.ge.s32 %p8, %rs2, %r10;
    @%p8 bra L_rowchk_done;
    setp.lt.s32 %p9, %r62, 0;
    @%p9 bra L_rowchk_next;
    rem.s32 %r63, %r62, %r12;
    setp.ne.s32 %p10, %r63, 0;
    @%p10 bra L_rowchk_next;
    div.s32 %r64, %r62, %r12;
    setp.ge.s32 %p11, %r64, %r5;
    @%p11 bra L_rowchk_next;
    mov.s32 %r75, 1;
    bra L_rowchk_done;
L_rowchk_next:
    sub.s32 %r62, %r62, %r16;           // t_h -= dh
    add.s32 %rs2, %rs2, 1;
    bra L_rowchk;
L_rowchk_done:
    setp.eq.s32 %p20, %r75, 0;
    @%p20 bra L_store;                  // no tap hits this row: store bias/zero
    // loop-invariant weight row base (tap-linear units)
    mul.lo.s32 %r57, %r34, %r10;
    mul.lo.s32 %r57, %r57, %r11;        // oc_g*kh*kw
    mov.s32 %rs2, 0;
    add.s32 %r62, %r28, %r14;           // t_h = oh + ph
    mov.s32 %r66, 0;                    // kh_i*kw
L_kh:
    setp.ge.s32 %p8, %rs2, %r10;
    @%p8 bra L_store;
    setp.lt.s32 %p9, %r62, 0;
    @%p9 bra L_kh_next;
    rem.s32 %r63, %r62, %r12;
    setp.ne.s32 %p10, %r63, 0;
    @%p10 bra L_kh_next;
    div.s32 %r64, %r62, %r12;           // ih
    setp.ge.s32 %p11, %r64, %r5;
    @%p11 bra L_kh_next;
    sub.s32 %r65, %r64, %r39;           // ih_off
    mul.lo.s32 %r65, %r65, %r38;        // input smem row base
    mov.s32 %rs3, 0;
    add.s32 %r68, %r35, %r15;           // t_a = ow + pw - kw_i*dw
    add.s32 %r76, %r74, %r15;           // t_b = ow_b + pw - kw_i*dw
    add.s32 %r87, %r85, %r15;           // t_c = ow_c + pw - kw_i*dw
    add.s32 %r88, %r86, %r15;           // t_d = ow_d + pw - kw_i*dw
L_kw:
    setp.ge.s32 %p12, %rs3, %r11;
    @%p12 bra L_kh_next;
    // tap validity for output a
    mov.s32 %r77, 0;
    mov.s32 %r78, 0;
    setp.lt.s32 %p13, %r68, 0;
    @%p13 bra L_va_done;
    rem.s32 %r69, %r68, %r13;
    setp.ne.s32 %p14, %r69, 0;
    @%p14 bra L_va_done;
    div.s32 %r70, %r68, %r13;           // iw_a
    setp.ge.s32 %p15, %r70, %r6;
    @%p15 bra L_va_done;
    sub.s32 %r77, %r70, %r41;
    add.s32 %r77, %r77, %r65;           // input smem offset for output a (ic=0)
    mov.s32 %r78, 1;
L_va_done:
    // tap validity for output b
    mov.s32 %r79, 0;
    mov.s32 %r80, 0;
    @!%p17 bra L_vb_done;
    setp.lt.s32 %p13, %r76, 0;
    @%p13 bra L_vb_done;
    rem.s32 %r69, %r76, %r13;
    setp.ne.s32 %p14, %r69, 0;
    @%p14 bra L_vb_done;
    div.s32 %r70, %r76, %r13;           // iw_b
    setp.ge.s32 %p15, %r70, %r6;
    @%p15 bra L_vb_done;
    sub.s32 %r79, %r70, %r41;
    add.s32 %r79, %r79, %r65;           // input smem offset for output b (ic=0)
    mov.s32 %r80, 1;
L_vb_done:
    // tap validity for output c
    mov.s32 %r89, 0;
    mov.s32 %r91, 0;
    @!%p22 bra L_vc_done;
    setp.lt.s32 %p13, %r87, 0;
    @%p13 bra L_vc_done;
    rem.s32 %r69, %r87, %r13;
    setp.ne.s32 %p14, %r69, 0;
    @%p14 bra L_vc_done;
    div.s32 %r70, %r87, %r13;           // iw_c
    setp.ge.s32 %p15, %r70, %r6;
    @%p15 bra L_vc_done;
    sub.s32 %r89, %r70, %r41;
    add.s32 %r89, %r89, %r65;           // input smem offset for output c (ic=0)
    mov.s32 %r91, 1;
L_vc_done:
    // tap validity for output d
    mov.s32 %r90, 0;
    mov.s32 %r92, 0;
    @!%p23 bra L_vd_done;
    setp.lt.s32 %p13, %r88, 0;
    @%p13 bra L_vd_done;
    rem.s32 %r69, %r88, %r13;
    setp.ne.s32 %p14, %r69, 0;
    @%p14 bra L_vd_done;
    div.s32 %r70, %r88, %r13;           // iw_d
    setp.ge.s32 %p15, %r70, %r6;
    @%p15 bra L_vd_done;
    sub.s32 %r90, %r70, %r41;
    add.s32 %r90, %r90, %r65;           // input smem offset for output d (ic=0)
    mov.s32 %r92, 1;
L_vd_done:
    setp.ne.s32 %p18, %r78, 0;          // valid_a
    setp.ne.s32 %p19, %r80, 0;          // valid_b
    setp.ne.s32 %p24, %r91, 0;          // valid_c
    setp.ne.s32 %p25, %r92, 0;          // valid_d
    or.pred %p21, %p18, %p19;
    or.pred %p26, %p24, %p25;
    or.pred %p21, %p21, %p26;
    @!%p21 bra L_kw_next;               // tap hits no register-blocked output
    add.s32 %r84, %r57, %r66;
    add.s32 %r84, %r84, %rs3;           // tap-linear weight index
    mul.lo.s32 %r84, %r84, %r96;        // weight smem float offset (ic=0)
    cvt.u64.s32 %rd19, %r84;
    mul.lo.u64 %rd19, %rd19, 4;
    add.u64 %rd19, %rd5, %rd19;         // weight pointer (contiguous over ic)
    mov.u64 %rd15, %rd9;
    mov.u64 %rd21, 0;
    @!%p18 bra L_pa_done;
    cvt.u64.s32 %rd15, %r77;
    mul.lo.u64 %rd15, %rd15, 4;
    add.u64 %rd15, %rd6, %rd15;
    mov.u64 %rd21, %rd14;
L_pa_done:
    mov.u64 %rd16, %rd9;
    mov.u64 %rd22, 0;
    @!%p19 bra L_pb_done;
    cvt.u64.s32 %rd16, %r79;
    mul.lo.u64 %rd16, %rd16, 4;
    add.u64 %rd16, %rd6, %rd16;
    mov.u64 %rd22, %rd14;
L_pb_done:
    mov.u64 %rd17, %rd9;
    mov.u64 %rd23, 0;
    @!%p24 bra L_pc_done;
    cvt.u64.s32 %rd17, %r89;
    mul.lo.u64 %rd17, %rd17, 4;
    add.u64 %rd17, %rd6, %rd17;
    mov.u64 %rd23, %rd14;
L_pc_done:
    mov.u64 %rd18, %rd9;
    mov.u64 %rd24, 0;
    @!%p25 bra L_pd_done;
    cvt.u64.s32 %rd18, %r90;
    mul.lo.u64 %rd18, %rd18, 4;
    add.u64 %rd18, %rd6, %rd18;
    mov.u64 %rd24, %rd14;
L_pd_done:
    mov.s32 %rs1, 0;
L_ic4:
    setp.lt.s32 %p7, %rs1, %r95;
    @!%p7 bra L_ic_tail;
    ld.shared.f32 %f1, [%rd15];
    add.u64 %rd20, %rd15, %rd21;
    ld.shared.f32 %f2, [%rd20];
    add.u64 %rd20, %rd20, %rd21;
    ld.shared.f32 %f21, [%rd20];
    add.u64 %rd20, %rd20, %rd21;
    ld.shared.f32 %f22, [%rd20];
    add.u64 %rd15, %rd20, %rd21;
    ld.shared.f32 %f6, [%rd16];
    add.u64 %rd20, %rd16, %rd22;
    ld.shared.f32 %f23, [%rd20];
    add.u64 %rd20, %rd20, %rd22;
    ld.shared.f32 %f24, [%rd20];
    add.u64 %rd20, %rd20, %rd22;
    ld.shared.f32 %f25, [%rd20];
    add.u64 %rd16, %rd20, %rd22;
    ld.shared.f32 %f7, [%rd17];
    add.u64 %rd20, %rd17, %rd23;
    ld.shared.f32 %f26, [%rd20];
    add.u64 %rd20, %rd20, %rd23;
    ld.shared.f32 %f27, [%rd20];
    add.u64 %rd20, %rd20, %rd23;
    ld.shared.f32 %f28, [%rd20];
    add.u64 %rd17, %rd20, %rd23;
    ld.shared.f32 %f8, [%rd18];
    add.u64 %rd20, %rd18, %rd24;
    ld.shared.f32 %f29, [%rd20];
    add.u64 %rd20, %rd20, %rd24;
    ld.shared.f32 %f30, [%rd20];
    add.u64 %rd20, %rd20, %rd24;
    ld.shared.f32 %f31, [%rd20];
    add.u64 %rd18, %rd20, %rd24;
    ld.shared.v4.f32 {%f11,%f12,%f13,%f14}, [%rd19];
    add.u64 %rd19, %rd19, 16;
    fma.rn.f32 %f3, %f1, %f11, %f3;
    fma.rn.f32 %f5, %f6, %f11, %f5;
    fma.rn.f32 %f9, %f7, %f11, %f9;
    fma.rn.f32 %f10, %f8, %f11, %f10;
